<script setup>
import { ref,reactive,computed,watch } from 'vue';import { useRoute } from 'vue-router';import { ArrowUpRight,Search,CalendarDays,Plus } from 'lucide-vue-next';import { api } from '../lib/api';import { currency,dateText } from '../lib/format';import StatusBadge from '../components/StatusBadge.vue';import StatePanel from '../components/StatePanel.vue';
const route=useRoute(),admin=computed(()=>route.meta.admin),rows=ref([]),loading=ref(true),error=ref(''),total=ref(0);const filters=reactive({page:1,limit:12,status:'',search:''});
async function load(){loading.value=true;error.value='';try{const q=new URLSearchParams({page:filters.page,limit:filters.limit});if(filters.status)q.set('status',filters.status);if(filters.search)q.set('search',filters.search);const result=await api((admin.value?'/admin/bookings':'/me/bookings')+'?'+q);rows.value=result.data;total.value=result.meta.total;}catch(e){error.value=e.message;}finally{loading.value=false;}}
function search(){filters.page=1;load();}watch(()=>route.path,()=>{filters.page=1;load();},{immediate:true});
</script>
<template><section :class="admin?'':'container section compact'"><div class="page-heading"><div><p class="eyebrow">{{ admin?'RESERVATIONS':'YOUR STAYS' }}</p><h1>{{ admin?'จัดการการจอง':'การจองของฉัน' }}</h1><p class="muted">{{ admin?'ตรวจสอบการจองและดูแลทุกการเข้าพัก':'ติดตามสถานะและจัดการรายละเอียดการพักผ่อนของคุณ' }}</p></div><RouterLink v-if="!admin" to="/rooms" class="btn primary"><Plus :size="18"/> จองห้องพักเพิ่ม</RouterLink></div><form class="toolbar panel" @submit.prevent="search"><div class="search-input"><Search :size="17"/><input v-model="filters.search" aria-label="ค้นหาเลขการจอง" placeholder="ค้นหาเลขการจอง"/></div><select v-model="filters.status" aria-label="กรองสถานะ"><option value="">ทุกสถานะ</option><option value="pending">รอตรวจสอบ</option><option value="confirmed">ยืนยันแล้ว</option><option value="checked_in">เข้าพักแล้ว</option><option value="checked_out">เช็กเอาต์แล้ว</option><option value="cancelled">ยกเลิก</option><option value="expired">หมดอายุ</option><option value="no_show">ไม่มาเข้าพัก</option></select><button class="btn outline">ค้นหา</button></form><StatePanel :loading="loading" :error="error" :empty="!loading&&!error&&!rows.length" @retry="load"><RouterLink to="/rooms" class="btn primary" v-if="!admin">ค้นหาห้องพัก</RouterLink></StatePanel><div v-if="!loading&&!error&&rows.length" class="panel table-panel"><div class="table-scroll"><table><thead><tr><th>เลขการจอง</th><th v-if="admin">ผู้เข้าพัก</th><th>วันเข้าพัก</th><th>วันเช็กเอาต์</th><th>ยอดค่าห้อง</th><th>สถานะ</th><th></th></tr></thead><tbody><tr v-for="b in rows" :key="b.booking_id"><td><strong>{{ b.booking_number }}</strong><small>{{ b.nights }} คืน · {{ b.adult_count }} ผู้ใหญ่ · {{ b.child_count }} เด็ก</small></td><td v-if="admin">{{ b.first_name }} {{ b.last_name }}</td><td>{{ dateText(b.check_in_date) }}</td><td>{{ dateText(b.check_out_date) }}</td><td>{{ currency(b.total_amount) }}</td><td><StatusBadge :value="b.booking_status"/></td><td><RouterLink :to="'/bookings/'+b.booking_id" class="btn tiny outline">ดูรายละเอียด <ArrowUpRight :size="15"/></RouterLink></td></tr></tbody></table></div></div><div v-if="total" class="pagination"><span>{{ total }} รายการ · หน้า {{ filters.page }} / {{ Math.ceil(total/filters.limit) }}</span><div><button class="btn outline tiny" :disabled="filters.page===1||loading" @click="filters.page--;load()">ก่อนหน้า</button><button class="btn outline tiny" :disabled="filters.page*filters.limit>=total||loading" @click="filters.page++;load()">ถัดไป</button></div></div></section></template>
